float Vignette(in vec2 fragCoord)
{
    #define kVignetteStrength         0.5             // The strength of the vignette effect
    #define kVignetteScale            0.9            // The scale of the vignette effect
    #define kVignetteExponent         4.0             // The rate of attenuation of the vignette effect

    vec2 uv = fragCoord / iResolution.xy;
    uv.x = (uv.x - 0.5) * (iResolution.x / iResolution.y) + 0.5;     

    float x = 2.0 * (uv.x - 0.5);
    float y = 2.0 * (uv.y - 0.5);

    float dist = sqrt(x*x + y*y) / kRoot2;

    return mix(1.0, max(0.0, 1.0 - pow(dist * kVignetteScale, kVignetteExponent)), kVignetteStrength);
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{
    SetGlobals(xyScreen, iResolution.xy, iTime); 

    // Composite
    vec3 rgb = saturate(texelFetch(iChannel0, ivec2(xyScreen), 0).xyz);

    // Colour grade
    vec3 hsv = RGBToHSV(rgb);    
    hsv.x += -sin((hsv.x - 0.1) * kTwoPi) * 0.05;
    hsv.y *= 1.2;    
    rgb = HSVToRGB(hsv);

    if(kApplyBloom) { rgb += 2.5 * SeparableBlurUp(ivec2(xyScreen), ivec2(iResolution.xy), iChannel1); }

    // Luminance grade
    rgb = pow(rgb, vec3(0.7)) * 0.9 + vec3(0.1);

    rgb *= Vignette(xyScreen);

    rgba.xyz = rgb;    
    rgba.w = 1.0;
}

