#define kApplyBloom               true
#define kBloomTint                vec3(1.0)       // The tint applied to the bloom effect
#define kBloomRadius              vec2(0.02)             // The width of the bloom effect as a proportion of the buffer width
#define kBloomKernelShape         vec3(1.0)             // The fall-off of the bloom shape. Higher value = steeper fall-off
#define kBloomDownsample          4              // How much the bloom buffer is downsampled. Higher value = lower quality, but faster
#define kDebugBloom               false           // Show only the bloom in the final comp
#define kBloomBurnIn              vec3(0.5)     

void Gaussian(in int k, in int radius, in vec3 rgbK, in vec3 kernelShape, inout vec3 sigmaL, inout vec3 sigmaWeights)
{
    float d = float(abs(k)) / float(radius);
    vec3 weight = pow(max(vec3(0.), (exp(-sqr(vec3(d) * 4.0)) - 0.0183156) / 0.981684), kernelShape);         

    sigmaL += rgbK * weight;
    sigmaWeights += weight;
}

void Epanechnikov(in int k, in int radius, in vec3 rgbK, in vec3 kernelShape, inout vec3 sigmaL, inout vec3 sigmaWeights)
{
    float d = float(abs(k)) / float(radius);
    float weight = 1. - d*d;

    sigmaL += rgbK * weight;
    sigmaWeights += weight;
}

//#define BlurKernel Gaussian
#define BlurKernel Epanechnikov

vec3 SeparableBlurDown(ivec2 xy, ivec2 res, sampler2D sampler)
{
    if(xy.y == 0 || xy.x >= res.x / kBloomDownsample || xy.y >= res.y / kBloomDownsample)
    {
        return kZero;
    }
    else
    {
        int radius = int(0.5 + float(min(res.x, res.y)) * kBloomRadius.x / float(kBloomDownsample));    
        vec3 sigmaL = kZero, sigmaWeights = kZero;
        for(int k = -radius; k <= radius; ++k)
        {
            ivec2 ij = (xy + ivec2(k, 0)) * kBloomDownsample;
            vec3 texel = texelFetch(sampler, ij, 0).xyz;
            texel = max(kZero, texel - vec3(kBloomBurnIn));
            BlurKernel(k, radius, texel, kBloomKernelShape, sigmaL, sigmaWeights);
        }

        return sigmaL / max(kOne, sigmaWeights);
    }
}

vec3 SeparableBlurUp(ivec2 xyFrag, ivec2 res, sampler2D sampler)
{   
    int radius = int(0.5 + float(min(res.x, res.y)) * kBloomRadius.y / float(kBloomDownsample));    
    vec3 sigmaL = kZero, sigmaWeights = kZero;
    for(int k = -radius; k <= radius; ++k)
    {        
        vec2 uv = (vec2(xyFrag + ivec2(0, k * kBloomDownsample)) - 0.5) / vec2(res);

        vec3 texel = texture(sampler, uv / float(kBloomDownsample), 0.0).xyz;

        BlurKernel(k, radius, texel, kBloomKernelShape, sigmaL, sigmaWeights);
    }

    return sigmaL / max(kOne, sigmaWeights);
}

#define kCaptureMode 0

#if kCaptureMode == 1
    #define kCaptureTimeDelay 10.0
    #define kCaptureTimeSpeed 0.25
#else
    #define kCaptureTimeDelay 0.0
    #define kCaptureTimeSpeed 1.0
#endif

vec3 Render(vec2 uvScreen, ivec2 idx)
{       
    #define kMBlurGain      50.0
    #define kMaxIterations  10
    #define kZoomOrder      3
    #define kEndPause       0.0
    #define kSpeed          0.25
    #define kDelayLength    3.0

    // Sample the time domain 
    //uint hash = HashOf(uint(98796523), uint(gFragCoord.x), uint(gFragCoord.y));
    //float xi = HaltonBase2(hash + uint(idx.x));
    float xi = OrderedDither(ivec2(uvScreen));
    xi = (float(idx.x) + xi) / float(idx.y);
    //float xi = OrderedDither();
    float time = max(0.0, iTime - kCaptureTimeDelay);
    time = (time * kCaptureTimeSpeed + 1.0 / 60.0 * xi * kMBlurGain) * kSpeed;     
    float phase = fract(time);    
    float breathe = pow(sin01(.8 * iTime), 1.5);

    // Sternographic view transformation
    vec2 uvView = TransformScreenToWorld(uvScreen);   
    if(!InverseSternograph(uvView, mix(0.9, 1.2, breathe))) { return kZero; }

    uvView *= mix(1., 0.7, breathe);

    // Define the view transformation matrix and clip to screen space
    mat3 M = WorldToViewMatrix(0.0, vec2(0.0), 0.15);
    uvView = (vec3(uvView, 1.0) * M).xy;   

    bool invert = false;
    float numIterations = float(kMaxIterations);
    uint hashIJ = 0u;
    vec3 bary;
    ivec2 ij;

    Cartesian2DToHexagonalTiling(uvView, bary, ij);        
    hashIJ = HashOf(ij);  

    vec3 L = kZero;

    for(int iterIdx = 0; iterIdx < kMaxIterations; ++iterIdx)
    {  
        float xi = HashToFloat(HashCombine(HashOf(uint(iterIdx)), hashIJ));
        float pulse = Impulse(phase, mix(0.1, 0.9, xi), 0.08);
        uvView *= mix(1.3, 0.75, pulse);

        Cartesian2DToHexagonalTiling(uvView, bary, ij);

        /*if(iterIdx == 0) 
        { 
            L += kOne * 0.01 * float((int(abs(20. * uvView.x)) + int(abs(20. * uvView.y))) % 2)  * 
                 saturate(1. - 0.05 * length(uvView)) * 
                 float(cwiseMax(bary) > 0.9); 
        }*/

        hashIJ = HashOf(ij);        

        float dist = 0.2 + length(vec2(ij) / vec2(1.0, 2.0 * 0.8660254037844387));   

        if(dist > 3.0) break;

        numIterations -= sqr(dist) * 1.5;
        if(float(iterIdx) >= numIterations) break;       

        uvView = BarycentricToCartesian2D(bary);  

        if(iterIdx == 0)
        {
            float theta = smoothstep(0., 1., saturate(21. * (2. * abs((fract(xi + iTime * 0.1)) - 0.5)) - 10.)) * kTwoPi / 6.;        
            uvView *= mat2(cos(theta), sin(theta), -sin(theta), cos(theta));            
        }

        if((hashIJ >> iterIdx) % 2u == uint(iterIdx % 2))
        {
            if(fract(2.0 * cwiseMax(abs(bary))) > 0.5)
            {
                invert = !invert;         
            }
        } 
    }

    return L + vec3(float(invert) * 0.7) * SampleSpectrum(xi);
}

void mainImage( out vec4 rgba, in vec2 xy )
{       
    SetGlobals(xy, iResolution.xy, iTime);   

    #define kAA 5
    vec3 sigma = vec3(0.0);
    for(int i = 0, idx = 0; i < kAA; ++i)
    {
        for(int j = 0; j < kAA; ++j, ++idx)
        {
            vec2 xyAA = xy + vec2(float(i) / float(kAA), float(j) / float(kAA));            

            sigma += Render(xyAA, ivec2(idx, kAA*kAA));
        }
    }    
    sigma /= float(kAA*kAA);

    rgba.xyz = sigma / vec3(1., 0.98, 0.98);    
    rgba.w = 1.0;
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{
    rgba *= 0.;

    // Apply first pass of separable bloom filter
    if(kApplyBloom)
    {    
        rgba = vec4(SeparableBlurDown(ivec2(xyScreen), ivec2(iResolution.xy), iChannel0), 1.);
    }
}
